                String[] fields = line.split(",");
                return new Tuple2<>(fields[0], fields[1]);
            }
        });

        // Cache the top queries for faster lookup
        Map<String, Long> queryCache = new HashMap<>();
        topQueries.collect().forEach(query -> queryCache.put(query, System.currentTimeMillis()));

