Create a `TooltipContext` to manage the state of the tooltip and provide a function to close it.

```jsx
import React, { createContext, useContext, useState } from 'react';

const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  const value = { tooltip, closeTooltip };

  return (
    <TooltipContext.Provider value={value}>{children}</TooltipContext.Provider>
  );
};

export const useTooltip = () => useContext(TooltipContext);
```

Create a `Tooltip` component that uses the `TooltipProvider` and `useTooltip` hook to open and close the tooltip.

```jsx
import React, { useRef, useState } from 'react';
import { TooltipProvider, useTooltip } from './TooltipContext';

const Tooltip = ({ children, placement = 'bottom', content }) => {
  const tooltipRef = useRef(null);
  const { tooltip, closeTooltip } = useTooltip();

  const handleMouseEnter = () => {
    if (!tooltip) {
      const tooltipRect = tooltipRef.current.getBoundingClientRect();
      const tooltipX = tooltipRect.left + window.pageXOffset;
      const tooltipY = tooltipRect.top + window.pageYOffset;

      setTooltip({ content, placement, tooltipX, tooltipY });
    }
  };

  const handleMouseLeave = () => {
    if (tooltip) {
      closeTooltip();
    }
  };

  return (
    <TooltipProvider>
      <div ref={tooltipRef} onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
        {children}
      </div>
      {tooltip && (
        <div
          className="tooltip"
          style={{ left: tooltip.tooltipX, top: tooltip.tooltipY, placement }}
        >
          {tooltip.content}
        </div>
      )}
    </TooltipProvider>
  );
};

export default Tooltip;
```

