To create a Chrome extension that takes screenshots of a webpage and saves them in a folder, follow these steps:

1. Create a new folder for your extension and navigate to it in your terminal.

2. Create a `manifest.json` file with the following content:

```json
{
  "manifest_version": 3,
  "name": "Webpage Screenshot",
  "version": "1.0",
  "action": {
    "default_popup": "popup.html",
    "default_icon": {
      "16": "images/icon16.png",
      "48": "images/icon48.png",
      "128": "images/icon128.png"
    }
  },
  "permissions": ["storage", "activeTab", "tabs", "downloads"],
  "background": {
    "service_worker": "background.js"
  },
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
      "js": ["content.js"]
    }
  ]
}
```

Replace the `images/icon16.png`, `images/icon48.png`, and `images/icon128.png` with the paths to your icons.

3. Create a `background.js` file with the following content:

```javascript
chrome.runtime.onInstalled.addListener(function() {
  chrome.storage.local.set({ screenshots: [] });
});

chrome.runtime.onMessageReceived.addListener(function(request, sender, sendResponse) {
  if (request.action === "saveScreenshot") {
    chrome.storage.local.get(["screenshots"], function(items) {
      const screenshots = items.screenshots || [];
      screenshots.push(request.screenshot);
      chrome.storage.local.set({ screenshots });
    });
  }
});
```

4. Create a `content.js` file with the following content:

```javascript
function takeScreenshot() {
  chrome.tabs.query({ active: true, currentWindow: true }, function(tabs) {
    chrome.tabs.sendMessage(tabs[0].id, { action: "takeScreenshot" });
  });
}

document.addEventListener("DOMContentLoaded", function() {
  const takeScreenshotButton = document.createElement("button");
  takeScreenshotButton.textContent = "Take Screenshot";
